import { createFileRoute } from "@tanstack/react-router";
import { useState } from "react";
import { createZip } from "@/lib/zip";

// routeTree.gen.ts is regenerated by the router plugin on every dev/build run.
// Base44's own server plumbing (start.js, server.js, error capture) is left out:
// the standalone game is client-only, and it builds without them.
const SOURCE = import.meta.glob(
  [
    "/src/**/*.{js,jsx,ts,tsx,css}",
    "!/src/routeTree.gen.ts",
    "!/src/start.js",
    "!/src/server.js",
    "!/src/lib/error-capture.js",
    "!/src/lib/error-capture.server.js",
  ],
  { query: "?raw", import: "default", eager: true },
);

const ROOT = import.meta.glob(
  [
    "/package.json",
    "/firebase.json",
    "/vite.config.firebase.js",
    "/tailwind.config.js",
    "/postcss.config.js",
    "/jsconfig.json",
    "/components.json",
    "/DEPLOY-FIREBASE.md",
    "/.gitignore",
    "/firebase/*",
  ],
  { query: "?raw", import: "default", eager: true },
);

function collectFiles() {
  return [...Object.entries(ROOT), ...Object.entries(SOURCE)].map(([path, content]) => ({
    path: path.replace(/^\//, ""),
    content,
  }));
}

export const Route = createFileRoute("/standalone")({
  ssr: false,
  head: () => ({ meta: [{ title: "The Last Auction — standalone project" }] }),
  component: StandalonePage,
});

function StandalonePage() {
  const [saved, setSaved] = useState(null);

  const download = () => {
    const files = collectFiles();
    const blob = createZip(files);
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "the-last-auction-standalone.zip";
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 5000);
    setSaved(`${files.length} files · ${(blob.size / 1024 / 1024).toFixed(2)} MB`);
  };

  return (
    <div className="mx-auto flex min-h-screen max-w-2xl flex-col justify-center px-6 py-16">
      <div className="rounded-sm bg-black/60 px-6 py-8 sm:px-10">
        <p className="text-[10px] uppercase tracking-[0.25em] text-foreground/50">Standalone copy</p>
        <h1 className="mt-4 font-heading text-3xl leading-tight sm:text-4xl">
          Everything the game needs, in one zip
        </h1>
        <p className="mt-5 text-[15px] leading-relaxed text-foreground/70">
          The archive holds the source, the Firebase build settings and the deploy notes. Unzip it,
          run <span className="font-mono text-foreground">npm install</span>, then{" "}
          <span className="font-mono text-foreground">npm run build:firebase</span> and deploy the
          folder it produces. Base44's own server plumbing is left out; the game runs entirely in
          the browser.
        </p>

        <button type="button" onClick={download} className="btn-game mt-8 px-8 py-3.5 text-[13px]">
          Download the zip
        </button>

        {saved && (
          <p className="mt-4 font-mono text-[11px] uppercase tracking-[0.2em] text-muted-foreground">
            {saved} saved
          </p>
        )}
      </div>
    </div>
  );
}